// Generated by npm run build:worker. Edit src modules and rebuild.
// These are normalized adapter snapshots, not raw API responses.
const known = value => typeof value === 'string' && value.trim() !== '' && value.toLowerCase() !== 'unknown';
const compact = value => String(value ?? '').replace(/\s/g, '').toUpperCase();
function identity(flight) {
  const { number, departure, arrival } = flight ?? {};
  const date = departure?.scheduled?.slice(0, 10);
  if (!known(number) || !known(departure?.airport) || !known(arrival?.airport) || !/^\d{4}-\d{2}-\d{2}$/.test(date ?? '')) {
    throw new Error('Comparison requires flight number, route, and scheduled departure date.');
  }
  return [compact(number), compact(departure.airport), compact(arrival.airport), date].join('|');
}

// Provider local timestamps use a space; normalize it before comparing instants.
function instant(value) {
  if (!known(value) || !/(Z|[+-]\d{2}:\d{2})$/.test(value)) return null;
  const parsed = Date.parse(value.replace(' ', 'T'));
  return Number.isFinite(parsed) ? parsed : null;
}

function compareFlights(previous, current) {
  const id = identity(current);
  if (previous && identity(previous) !== id) throw new Error('Cannot compare different flights, routes, or departure dates.');
  const snapshot = structuredClone(current);
  const events = [];
  if (!previous) return { snapshot, events }; // First observation establishes a baseline.

  const add = (type, field, before, after, extra = {}) => {
    events.push({ type, field, before, after, ...extra });
  };
  const oldStatus = previous.status;
  if (!known(current.status)) snapshot.status = oldStatus;
  else if (known(oldStatus) && compact(oldStatus) !== compact(current.status)) {
    add(compact(current.status) === 'CANCELED' || compact(current.status) === 'CANCELLED' ? 'cancellation' : 'status_changed', 'status', oldStatus, current.status);
  }

  for (const side of ['departure', 'arrival']) {
    snapshot[side] ??= {};
    for (const field of ['gate', 'terminal', 'scheduled', 'revised']) {
      const before = previous[side]?.[field];
      const after = current[side]?.[field];
      // Missing fields are not evidence of a real change. Preserve the last known
      // value for comparison only; display freshness from the current observation.
      if (!known(after)) snapshot[side][field] = before ?? null;
      if (['gate', 'terminal'].includes(field) && known(before) && known(after) && compact(before) !== compact(after)) {
        add(`${field}_changed`, `${side}.${field}`, before, after);
      }
    }
    const before = previous[side]?.revised ?? previous[side]?.scheduled;
    const after = current[side]?.revised;
    const a = instant(before), b = instant(after);
    if (a !== null && b !== null && a !== b) {
      add('time_changed', `${side}.revised`, before, after, { minutesChanged: (b - a) / 60000 });
    }
    const oldScheduled = previous[side]?.scheduled;
    const newScheduled = current[side]?.scheduled;
    const s1 = instant(oldScheduled), s2 = instant(newScheduled);
    if (s1 !== null && s2 !== null && s1 !== s2) add('schedule_changed', `${side}.scheduled`, oldScheduled, newScheduled, { minutesChanged: (s2 - s1) / 60000 });
  }
  return { snapshot, events };
}

function validateInput(number, date) {
  const flight = String(number ?? '').replace(/\s/g, '').toUpperCase();
  if (!/^[A-Z0-9]{2,3}\d{1,4}[A-Z]?$/.test(flight) || !/[A-Z]/.test(flight.slice(0, 3))) throw new Error('Enter a flight number such as AA100.');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date ?? '') || !Number.isFinite(Date.parse(date)) || new Date(date).toISOString().slice(0, 10) !== date) throw new Error('Enter a real departure date as YYYY-MM-DD.');
  return { flight, date };
}

function normalizeFlights(data) {
  if (!Array.isArray(data)) throw new Error('Unexpected provider response: expected a list of flights.');
  return data.map(f => {
    if (!f || typeof f !== 'object') throw new Error('Unexpected flight record.');
    const movement = m => ({
      airport: m?.airport?.iata ?? m?.airport?.icao ?? null,
      airportName: m?.airport?.name ?? null,
      countryCode: m?.airport?.countryCode ?? null,
      scheduled: m?.scheduledTime?.local ?? m?.scheduledTime?.utc ?? null,
      revised: m?.revisedTime?.local ?? m?.revisedTime?.utc ?? null,
      terminal: m?.terminal ?? null, gate: m?.gate ?? null,
      quality: m?.quality ?? []
    });
    return { number: f.number ?? null, airline: f.airline?.name ?? null, airlineCode: f.airline?.iata ?? f.airline?.icao ?? null,
      status: f.status ?? 'Unknown', departure: movement(f.departure), arrival: movement(f.arrival) };
  });
}

async function lookup({ flight, date, key, fetchImpl = fetch }) {
  const url = new URL(`https://aerodatabox.p.rapidapi.com/flights/number/${encodeURIComponent(flight)}/${date}`);
  url.search = new URLSearchParams({ dateLocalRole: 'Departure', withFlightPlan: 'false', withAircraftImage: 'false', withLocation: 'false' });
  const response = await fetchImpl(url, { headers: { 'X-RapidAPI-Key': key, 'X-RapidAPI-Host': url.hostname, Accept: 'application/json' }, signal: AbortSignal.timeout(15000), redirect: 'error' });
  if (response.status === 204) return [];
  if (!response.ok) {
    const messages = { 401: 'API key was rejected.', 403: 'Access denied. Check the subscription and key.', 429: 'Provider quota or rate limit reached. No retry was made.' };
    throw new Error(messages[response.status] ?? `Provider returned HTTP ${response.status}. No retry was made.`);
  }
  return normalizeFlights(await response.json());
}


function flightKey(flight, source) {
  compareFlights(null, flight); // Validate identity before any database request.
  if (!['synthetic', 'aerodatabox'].includes(source)) throw new Error('Unknown data source.');
  return [source, flight.number.replace(/\s/g, '').toUpperCase(), flight.departure.airport.toUpperCase(), flight.arrival.airport.toUpperCase(), flight.departure.scheduled.slice(0, 10)].join('|');
}

function createStorage({ url, key, fetchImpl = fetch }) {
  if (!url || !key) throw new Error('Add SUPABASE_URL and SUPABASE_SECRET_KEY to .env. See DATABASE-SETUP.md.');
  const base = new URL(url);
  if (base.protocol !== 'https:' || !base.hostname.endsWith('.supabase.co') || base.username || base.password || base.port || base.pathname !== '/' || base.search || base.hash) throw new Error('Use your HTTPS Supabase project URL, e.g. https://PROJECT.supabase.co');
  if (!key.startsWith('sb_secret_')) throw new Error('Use a backend Supabase secret key (sb_secret_...), not a publishable key.');
  async function request(path, body) {
    const response = await fetchImpl(new URL(`/rest/v1/${path}`, base), {
      method: body ? 'POST' : 'GET',
      headers: { apikey: key, 'Content-Type': 'application/json' },
      ...(body ? { body: JSON.stringify(body) } : {}),
      signal: AbortSignal.timeout(15000), redirect: 'error'
    });
    if (!response.ok) throw new Error(`Database request failed (HTTP ${response.status}). Check the project, secret key, and migration. No secrets or response bodies were logged.`);
    return response.json();
  }
  return {
    async save(flight, { source = 'synthetic', observedAt = new Date().toISOString(), observationId = crypto.randomUUID() } = {}) {
      if (!Number.isFinite(Date.parse(observedAt))) throw new Error('Invalid observation time.');
      const id = flightKey(flight, source);
      for (let attempt = 0; attempt < 3; attempt++) {
        const query = new URLSearchParams({ id: `eq.${id}`, select: 'version,comparison_state,observed_at,expires_at' });
        const rows = await request(`flight_tracks?${query}`);
        if (!Array.isArray(rows)) throw new Error('Unexpected database response.');
        const row = rows[0];
        const previous = row?.expires_at && Date.parse(row.expires_at) > Date.now() ? row.comparison_state : null;
        const { snapshot, events } = compareFlights(previous, flight);
        const result = await request('rpc/save_flight_observation', {
          p_id: observationId, p_flight_id: id, p_source: source, p_expected_version: row?.version ?? 0,
          p_observed_at: observedAt, p_snapshot: flight, p_state: snapshot, p_events: events
        });
        if (result.result !== 'conflict') return { ...result, flightId: id };
      }
      throw new Error('Flight changed concurrently. Retry this same observation ID later.');
    }
  };
}


async function runWorker({ rpc, storage, lookupFlight }) {
  const claim = await rpc('claim_flight_check', {});
  if (claim.result !== 'claimed') return { result: claim.result };
  const target = claim.flight;
  let outcome = 'failed', stop = false;
  try {
    const input = validateInput(target.number, target.departure_date);
    const flights = await lookupFlight(input);
    const expectedKey = ['aerodatabox', input.flight, target.origin, target.destination, input.date].join('|');
    const matches = flights.filter(f => {
      try { return flightKey(f, 'aerodatabox') === expectedKey; } catch { return false; }
    });
    if (!matches.length) outcome = 'no_match';
    else if (matches.length !== 1) { outcome = 'ambiguous'; stop = true; }
    else if (matches[0].departure.countryCode !== 'US' || matches[0].arrival.countryCode !== 'US') {
      outcome = 'unsupported_route'; stop = true;
    } else {
      const flight = matches[0];
      const saved = await storage.save(flight, { source: 'aerodatabox', observedAt: new Date().toISOString(), observationId: claim.attempt_id });
      if (!['saved', 'duplicate', 'stale'].includes(saved.result)) throw new Error('Unexpected save result');
      outcome = saved.result;
      stop = ['arrived', 'canceled', 'cancelled', 'diverted'].includes(String(flight.status).toLowerCase());
    }
  } catch {
    // Failure consumes the reservation; no provider retry. Pause until operator
    // review instead of repeatedly spending quota on a broken configuration.
    stop = true;
  }
  await rpc('finish_flight_check', { p_attempt_id: claim.attempt_id, p_outcome: outcome, p_stop: stop });
  return { result: outcome, stopped: stop };
}

function createWorkerHandler(env, fetchImpl = fetch) {
  return async request => {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 });
    const secret = env('WORKER_CRON_SECRET');
    if (!secret || secret.length < 32 || request.headers.get('x-worker-secret') !== secret) return new Response('Unauthorized', { status: 401 });
    // A second explicit kill switch prevents accidental live activation on deploy.
    if (env('WORKER_LIVE_ENABLED') !== 'true') return Response.json({ result: 'disabled' });
    try {
      const url = env('SUPABASE_URL');
      const key = env('WORKER_DB_SECRET');
      const rapidKey = env('RAPIDAPI_KEY');
      if (!rapidKey) throw new Error('Missing flight key');
      const storage = createStorage({ url, key, fetchImpl }); // Validates endpoint before RPC.
      const rpc = async (name, body) => {
        const response = await fetchImpl(`${url.replace(/\/$/, '')}/rest/v1/rpc/${name}`, {
          method: 'POST', headers: { apikey: key, 'Content-Type': 'application/json' },
          body: JSON.stringify(body), signal: AbortSignal.timeout(15000), redirect: 'error'
        });
        if (!response.ok) throw new Error('Database RPC failed');
        return response.json();
      };
      const result = await runWorker({ rpc, storage, lookupFlight: input => lookup({ ...input, key: rapidKey, fetchImpl }) });
      console.info(JSON.stringify({ worker: 'flight-worker', ...result }));
      return Response.json(result);
    } catch {
      return Response.json({ result: 'worker_error', message: 'Check database setup and function secrets. No automatic provider retry.' }, { status: 500 });
    }
  };
}

Deno.serve(createWorkerHandler(name => Deno.env.get(name)));
